                w = (x + y + z) % p
                h[w] += f[x] * f[y] * g[z] * g[w] # Wait, this is wrong.
    # Let me re-write this.

    # Correct way to compute h(k) = count of (x,y,z,w) such that x+y+z-w = k mod p
    # This is a convolution.
    # h = f * f * g * (g reversed)

    # Let's just use the 4-loop.
    h = [0] * p
    for x in range(p):
        for y in range(p):
