def solve_sq():
    p = 61
    f = [0] * p
    for a in range(p):
        f[a**2 % p] += 1

    h = [0] * p
    for x in range(p):
        for y in range(p):
            for z in range(p):
                for w in range(p):
                    if (x + y + z - w) % p == 0:
                        h[0] += f[x] * f[y] * f[z] * f[w]
    return h[0]

print(solve_sq())

def solve_zero():
    count = 0
    for a in range(1, 62):
        for b in range(1, 62):
            for c in range(1, 62):
                d_cubed = a**2 + b**2 + c**3
                d = round(d_cubed**(1/3))
                if d**3 == d_cubed and 1 <= d <= 61:
                    count += 1
    return count

print(solve_zero())

def solve_61():
    count = 0
    for a in range(1, 62):
        for b in range(1, 62):
            for c in range(1, 62):
                d_cubed = a**2 + b**2 + c**3 - 61
                if d_cubed > 0:
                    d = round(d_cubed**(1/3))
                    if d**3 == d_cubed and 1 <= d <= 61:
                        count += 1
    return count

print(solve_61())

