def solve_c3d3_values():
    p = 61
    g = [0] * p
    for c in range(p):
        g[c**3 % p] += 1

    m = [0] * p
    for z in range(p):
        for w in range(p):
            m[(z - w) % p] += g[z] * g[w]
    return m

